import unicodedata
ROWS=[]
def slug(x):return ''.join(c for c in unicodedata.normalize('NFKD',x.lower()) if not unicodedata.combining(c)).replace(',','').replace(' ','-')
def add(sector,title,profile,topic,env,mechanism,story,camera,blocking,labels,inputs):
 states=story.split('|');shots=camera.split('|');positions=blocking.split('|');names=labels.split('|');assert all(len(x)==4 for x in [states,shots,positions,names]),title
 kind='real_estate' if sector=='corretores' else 'implant_education'
 ROWS.append({'id':'explicador-'+sector+'-'+slug(title),'name':title,'sector':sector,'sectorName':'Corretores e imóveis' if sector=='corretores' else 'Dentistas e odontologia','environment':env,'topic':topic,'mechanism':mechanism,'states':states,'variantIndex':len(ROWS),'requiredInputs':inputs.split('|'),'domain':{'kind':kind,'profile':profile,'purpose':topic,'sourceVerificationRequired':True,'fictionalReferenceOnly':True},'customDirection':{'structure':profile+' · '+mechanism.replace('_',' '),'labels':names,'camera':shots,'blocking':positions,'graphicEvolution':states,'typography':'Serifada editorial contemporânea com sans humanista para dados; alinhamento preciso, amplo respiro e uma cor extra do ambiente.' if profile=='alto padrão' else 'Sans humanista moderna, hierarquia clara no celular, peso contrastante e uma cor de destaque com função.','layerOrder':['original_environment','explanatory_element_behind','original_presenter_or_observed_hands','explanatory_foreground'],'layerPolicy':'Contato e oclusão somente com máscara temporal, âncoras e tomadas verificadas; novas vistas precisam de mídia ou geometria autorizada.','sourceTimes':None,'motionValidated':False}})
